/**
  *  Generates Function Call-Fixup Fields.
  */
public class FunctionCallFixupFieldFactory : FieldFactory {

	public static readonly string FIELD_NAME = "Function Call-Fixup";

	/**
	 * Default Constructor
	 */
	public FunctionCallFixupFieldFactory() : base(FIELD_NAME)
    {
	}

	/**
	 * Constructor
	 * @param model the model that the field belongs to.
	 * @param hlProvider the HightLightProvider.
	 * @param displayOptions the Options for display properties.
	 * @param fieldOptions the Options for field specific properties.
	 */
	public FunctionCallFixupFieldFactory(FieldFormatModel model, ListingHighlightProvider hlProvider,
			Options displayOptions, Options fieldOptions) : base(FIELD_NAME, model, hlProvider, displayOptions, fieldOptions)
    {

	}

	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		object obj = proxy.getObject();
		if (!enabled || !(obj is Function)) {
			return null;
		}
		Function f = (Function) obj;
		string callFixupStr = f.getCallFixup();
		if (callFixupStr == null) {
			return null;
		}

		List<FieldElement> textElements = new();
		AttributedString @as;
		int elementIndex = 0;

		@as = new AttributedString("Call-Fixup: ", ListingColors.SEPARATOR, getMetrics());
		textElements.add(new TextFieldElement(@as, elementIndex++, 0));

		@as = new AttributedString(callFixupStr, FunctionColors.CALL_FIXUP, getMetrics());
		textElements.add(new TextFieldElement(@as, elementIndex++, 0));

		return ListingTextField.createSingleLineTextField(this, proxy,
			new CompositeFieldElement(textElements), startX + varWidth, width, hlProvider);
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int col, ListingField bf) {
		ProxyObj<object> proxy = bf.getProxy();
		if (proxy is FunctionProxy) {
			FunctionProxy functionProxy = (FunctionProxy) proxy;
			Function function = functionProxy.getObject();
			return new FunctionCallFixupFieldLocation(function.getProgram(),
				functionProxy.getLocationAddress(), functionProxy.getFunctionAddress(),
				function.getCallFixup(), col);
		}

		return null;
	}

	/* @Override */
	public FieldLocation getFieldLocation(ListingField bf, BigInteger index, int fieldNum,
			ProgramLocation loc) {

		if (loc is FunctionCallFixupFieldLocation) {
			FunctionCallFixupFieldLocation callFixupLoc = (FunctionCallFixupFieldLocation) loc;
			return new FieldLocation(index, fieldNum, 0, callFixupLoc.getCharOffset());
		}
		return null;
	}

	/* @Override */
	public bool acceptsType(int category, Class<object> proxyObjectClass) {
		if (!typeof(Function).isAssignableFrom(proxyObjectClass)) {
			return false;
		}
		return (category == FieldFormatModel.FUNCTION);
	}

	/* @Override */
	public FieldFactory newInstance(FieldFormatModel formatModel, ListingHighlightProvider provider,
			ToolOptions displayOptions, ToolOptions fieldOptions) {
		return new FunctionCallFixupFieldFactory(formatModel, provider, displayOptions,
			fieldOptions);
	}

}
